-- Explicações por artigo — Lei de Drogas (Lei nº 11.343, de 2006). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei de Drogas institui o Sisnad (Sistema Nacional de Políticas Públicas sobre Drogas), prescreve medidas de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes, estabelece normas de repressão à produção não autorizada e ao tráfico ilícito e define crimes. Drogas são as substâncias ou produtos capazes de causar dependência, especificados em lei ou em listas atualizadas periodicamente pelo Poder Executivo da União.', '["Institui o Sisnad.","Prevenção, atenção e reinserção social de usuários e dependentes.","Repressão à produção não autorizada e ao tráfico.","Droga: substância capaz de causar dependência, definida em lei ou em lista do Poder Executivo."]'::jsonb, '["A definição de ''droga'' depende de lista atualizada pelo Executivo (norma penal em branco).","A lista é a Portaria SVS/MS nº 344, de 1998, e suas atualizações."]'::jsonb, 'Uma nova substância incluída na lista oficial passa a ser ''droga'' para os efeitos penais.', '["Assertiva que define droga por critério exclusivamente jurídico, sem a lista oficial do Poder Executivo, erra."]'::jsonb, '[{"termo":"Norma penal em branco","significado":"Norma cuja descrição depende de complemento por outra norma."}]'::jsonb, '["Art. 2º","Art. 66"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ficam proibidas, em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar e o uso estritamente ritualístico-religioso da Convenção de Viena de 1971. A União pode autorizar o plantio, a cultura e a colheita desses vegetais exclusivamente para fins medicinais ou científicos, em local e prazo predeterminados, mediante fiscalização.', '["Proibição geral de drogas e do cultivo de vegetais que as produzam.","Ressalvas: autorização legal ou regulamentar e plantas de uso ritualístico-religioso.","Parágrafo único: a União pode autorizar plantio para fins medicinais ou científicos."]'::jsonb, '["A autorização é da UNIÃO e exclusiva para fins MEDICINAIS ou CIENTÍFICOS.","A proibição abrange também as plantas, e não só as substâncias."]'::jsonb, 'Pesquisa científica com planta autorizada pela União, em local e prazo definidos, é lícita.', '["Assertiva que permite ao Estado autorizar o plantio de plantas psicotrópicas para fins medicinais erra: a competência é da União."]'::jsonb, '[]'::jsonb, '["Art. 1º","Art. 33, §1º, II"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão da produção não autorizada e do tráfico ilícito. Sisnad é o conjunto ordenado de princípios, regras, critérios e recursos materiais e humanos das políticas sobre drogas, incluindo por adesão os sistemas dos Estados, do Distrito Federal e dos Municípios. Atua em articulação com o SUS e o SUAS.', '["Duas frentes: prevenção, atenção e reinserção; e repressão.","Estados, DF e Municípios integram por adesão.","Atuação articulada com o SUS e o SUAS."]'::jsonb, '["ATUALIZAÇÃO: §§ 1º e 2º incluídos pela Lei nº 13.840, de 2019."]'::jsonb, 'Um município adere ao Sisnad e integra sua política local sobre drogas.', '["Assertiva que torna obrigatória a integração dos Municípios ao Sisnad erra: é por adesão."]'::jsonb, '[{"termo":"Sisnad","significado":"Sistema Nacional de Políticas Públicas sobre Drogas."}]'::jsonb, '["Art. 4º","Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São princípios do Sisnad, entre outros, o respeito aos direitos fundamentais, especialmente à autonomia e à liberdade; o respeito à diversidade; a promoção dos valores éticos, culturais e de cidadania; a promoção de consensos nacionais; a responsabilidade compartilhada entre Estado e sociedade; o reconhecimento da intersetorialidade dos fatores; a integração das estratégias nacionais e internacionais; a articulação com o Ministério Público e os Poderes Legislativo e Judiciário; e a abordagem multidisciplinar.', '["Respeito aos direitos fundamentais, à autonomia e à liberdade.","Respeito à diversidade.","Responsabilidade compartilhada entre Estado e sociedade.","Intersetorialidade e abordagem multidisciplinar.","Articulação com o MP e os Poderes."]'::jsonb, '["Rol de princípios, cobrado literalmente em provas."]'::jsonb, 'A política local de drogas envolve saúde, educação e assistência social: intersetorialidade.', '["Assertiva que exclui o respeito à diversidade dos princípios do Sisnad erra."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Sisnad tem os seguintes objetivos: contribuir para a inclusão social do cidadão, tornando-o menos vulnerável a comportamentos de risco; promover a construção e a socialização do conhecimento sobre drogas no país; promover a integração entre as políticas de prevenção, atenção e reinserção e de repressão e as políticas setoriais dos órgãos do Poder Executivo; e assegurar as condições para a coordenação, a integração e a articulação das atividades do art. 3º.', '["Inclusão social.","Construção e socialização do conhecimento sobre drogas.","Integração entre as políticas de prevenção e repressão e as políticas setoriais.","Coordenação, integração e articulação das atividades."]'::jsonb, '["Quatro objetivos."]'::jsonb, 'Programa de qualificação profissional para jovens vulneráveis atende ao objetivo de inclusão social.', '["Assertiva que lista cinco objetivos do Sisnad, incluindo o julgamento de crimes, erra."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

