insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à União formular e coordenar a execução da Política Nacional sobre Drogas; elaborar o Plano Nacional de Políticas sobre Drogas, em parceria com Estados, Distrito Federal, Municípios e a sociedade; coordenar o Sisnad; estabelecer diretrizes e normas de referência; elaborar objetivos, ações estratégicas, metas e indicadores e definir formas de financiamento e gestão; promover a integração com os demais entes; financiar, com eles, a execução das políticas; e estabelecer formas de colaboração com os entes federados, entre outras competências.', '["Formular e coordenar a Política Nacional sobre Drogas.","Elaborar o Plano Nacional.","Coordenar o Sisnad.","Integrar e financiar com Estados, DF e Municípios."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído pela Lei nº 13.840, de 2019.","Os incisos VI e VII foram vetados."]'::jsonb, 'A União elabora o Plano Nacional em parceria com Estados e Municípios.', '["Assertiva que atribui ao Município a coordenação do Sisnad erra: é da União."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
