insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As atividades de atenção e de reinserção social do usuário e do dependente e de seus familiares devem observar princípios como o respeito ao usuário independentemente de quaisquer condições; estratégias diferenciadas conforme as peculiaridades socioculturais; projeto terapêutico individualizado; atenção multidisciplinar, por equipes multiprofissionais; observância das normas do Conad; alinhamento às diretrizes dos órgãos de controle social; estímulo à capacitação técnica e profissional; e políticas de reinserção voltadas à educação continuada e ao trabalho.', '["Respeito ao usuário, independentemente de condições.","Projeto terapêutico individualizado.","Atenção multidisciplinar.","Observância das normas do Conad.","Capacitação e políticas de educação continuada e trabalho."]'::jsonb, '["ATUALIZAÇÃO: incisos VII e VIII incluídos pela Lei nº 13.840, de 2019."]'::jsonb, 'A equipe multiprofissional elabora um projeto terapêutico individual para cada usuário.', '["Assertiva que dispensa o projeto terapêutico individualizado erra."]'::jsonb, '[{"termo":"Conad","significado":"Conselho Nacional de Políticas sobre Drogas."}]'::jsonb, '["Art. 23-B"]'::jsonb, 'under_review', 'claude'
