insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As redes dos serviços de saúde da União, dos Estados, do Distrito Federal e dos Municípios desenvolverão programas de atenção ao usuário e ao dependente de drogas, respeitadas as diretrizes do Ministério da Saúde e os princípios do art. 22, obrigatória a previsão orçamentária adequada. Será criada estratégia específica de assistência multiprofissional e interdisciplinar às mulheres usuárias e dependentes de álcool, em especial às gestantes e às puérperas.', '["Redes de saúde de todos os entes desenvolvem programas de atenção.","Previsão orçamentária obrigatória.","Estratégia específica para mulheres usuárias de álcool, especialmente gestantes e puérperas."]'::jsonb, '["ATUALIZAÇÃO: parágrafo único incluído pela Lei nº 15.581, de 2025 (mulheres usuárias de álcool)."]'::jsonb, 'A rede municipal cria atendimento especializado a gestantes dependentes de álcool.', '["Assertiva que dispensa previsão orçamentária para os programas de atenção erra: é obrigatória."]'::jsonb, '[]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-23'
