insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O tratamento do usuário ou dependente de drogas deverá ser ordenado em uma rede de atenção à saúde, com prioridade para as modalidades ambulatoriais, incluindo excepcionalmente formas de internação em unidades de saúde e hospitais gerais, nos termos de normas da União e articuladas com os serviços de assistência social, em etapas que permitam articular a atenção com ações preventivas; orientar-se por protocolos técnicos baseados em evidências; preparar para a reinserção social e econômica; e acompanhar os resultados pelo SUS, Suas e Sisnad. Caberá à União dispor sobre os protocolos técnicos de tratamento.', '["Prioridade ao tratamento ambulatorial; internação é exceção.","Protocolos técnicos baseados em evidências científicas.","Preparação para a reinserção social e econômica.","União dispõe sobre os protocolos técnicos."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.840, de 2019.","A internação é EXCEPCIONAL."]'::jsonb, 'O usuário é atendido em ambulatório, e a internação só ocorre em caso excepcional.', '["Assertiva que torna a internação a modalidade prioritária de tratamento erra: a prioridade é ambulatorial."]'::jsonb, '[]'::jsonb, '["Art. 23-B"]'::jsonb, 'under_review', 'claude'
