on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O atendimento ao usuário ou dependente de drogas na rede de atenção à saúde dependerá de avaliação prévia por equipe técnica multidisciplinar e multissetorial e da elaboração de um Plano Individual de Atendimento (PIA). A avaliação levantará no mínimo o tipo de droga e o padrão de seu uso e o risco à saúde física e mental do usuário ou das pessoas com as quais convive. O PIA deverá contemplar a participação dos familiares ou responsáveis, os quais têm o dever de contribuir com o processo, sendo passíveis de responsabilização, no caso de crianças e adolescentes, nos termos do Estatuto da Criança e do Adolescente.', '["Avaliação prévia por equipe multidisciplinar e multissetorial.","Plano Individual de Atendimento (PIA).","Avaliação: tipo de droga, padrão de uso e riscos.","Participação dos familiares ou responsáveis no PIA."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.840, de 2019.","Dois requisitos: avaliação prévia E PIA."]'::jsonb, 'Antes do atendimento, a equipe avalia o padrão de uso e elabora o PIA com a família.', '["Assertiva que dispensa a avaliação prévia da equipe técnica para o atendimento erra."]'::jsonb, '[{"termo":"PIA","significado":"Plano Individual de Atendimento."}]'::jsonb, '["Art. 23-A","Art. 26-A"]'::jsonb, 'under_review', 'claude'
