insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O acolhimento do usuário ou dependente de drogas na comunidade terapêutica acolhedora caracteriza-se pela oferta de projetos terapêuticos que visam à abstinência; adesão e permanência voluntária, formalizadas por escrito, como etapa transitória para a reinserção; ambiente residencial propício à formação de vínculos; avaliação médica prévia; elaboração de plano individual de atendimento; e vedação de isolamento físico do usuário.', '["Projeto terapêutico visando à abstinência.","Adesão e permanência VOLUNTÁRIAS, por escrito.","Ambiente residencial.","Avaliação médica prévia e PIA.","Vedado o isolamento físico."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.840, de 2019.","Acolhimento é voluntário e não se confunde com internação compulsória."]'::jsonb, 'O usuário adere por escrito ao acolhimento na comunidade terapêutica e pode sair quando quiser.', '["Assertiva que admite o isolamento físico do acolhido na comunidade terapêutica erra: é vedado."]'::jsonb, '[{"termo":"Comunidade terapêutica acolhedora","significado":"Entidade de acolhimento voluntário, de caráter residencial e transitório."}]'::jsonb, '["Art. 23-B"]'::jsonb, 'under_review', 'claude'
