insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas previstas para o usuário (art. 28) poderão ser aplicadas isolada ou cumulativamente, bem como substituídas a qualquer tempo, ouvidos o Ministério Público e o defensor.', '["Penas do art. 28 podem ser isoladas ou cumulativas.","Podem ser substituídas a qualquer tempo.","Ouvidos o MP e o defensor."]'::jsonb, '["O texto remete a debate no STF (RE 635659) sobre o art. 28."]'::jsonb, 'O juiz substitui a prestação de serviços por advertência, ouvidos o MP e o defensor.', '["Assertiva que impede a substituição das penas do art. 28 após a sentença erra: pode ocorrer a qualquer tempo."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
