on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quem adquirir, guardar, tiver em depósito, transportar ou trouxer consigo, para consumo pessoal, drogas sem autorização ou em desacordo com determinação legal ou regulamentar será submetido a advertência sobre os efeitos das drogas, prestação de serviços à comunidade e medida educativa de comparecimento a programa ou curso educativo. Às mesmas medidas submete-se quem, para seu consumo pessoal, semeia, cultiva ou colhe plantas destinadas à preparação de pequena quantidade de substância capaz de causar dependência. Para determinar se a droga destinava-se a consumo pessoal, o juiz atenderá à natureza e à quantidade da substância, ao local e às condições da ação, às circunstâncias sociais e pessoais e à conduta e aos antecedentes do agente. As penas dos incisos II e III duram no máximo 5 meses (10 meses na reincidência).', '["Núcleos: adquirir, guardar, ter em depósito, transportar ou trazer consigo, para consumo pessoal.","Penas: advertência, prestação de serviços à comunidade e curso educativo (sem prisão).","§1º: cultivo para consumo pessoal.","§2º: critérios para distinguir usuário de traficante.","Prazo máximo: 5 meses; reincidência: 10 meses."]'::jsonb, '["O art. 28 NÃO prevê pena privativa de liberdade (despenalização).","O STF discute a constitucionalidade do artigo (RE 635659).","Prazo de 5 meses (10 na reincidência) para as penas dos incisos II e III."]'::jsonb, 'Quem é flagrado com pequena quantidade para uso próprio é advertido e pode prestar serviços à comunidade.', '["Assertiva que prevê pena de detenção para o porte para consumo pessoal erra: o art. 28 não prevê pena de prisão."]'::jsonb, '[{"termo":"Despenalização","significado":"Retirada da pena de prisão, mantendo o fato como infração."}]'::jsonb, '["Art. 33","Art. 48"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-28'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na imposição da multa prevista como medida educativa ao usuário que se recusa a cumprir as medidas (art. 28, §6º, II), o juiz, atendendo à reprovabilidade da conduta, fixará o número de dias-multa, em quantidade nunca inferior a 40 nem superior a 100, atribuindo depois a cada um, segundo a capacidade econômica do agente, o valor de um trinta avos até 3 vezes o valor do maior salário mínimo. Os valores da multa serão creditados à conta do Fundo Nacional Antidrogas.', '["Multa de 40 a 100 dias-multa.","Valor do dia-multa: de um trinta avos até 3 vezes o maior salário mínimo.","Valores creditados ao Funad."]'::jsonb, '["A multa só incide sobre quem se recusa a cumprir as medidas do art. 28."]'::jsonb, 'O usuário que se recusa a cumprir as medidas paga multa fixada entre 40 e 100 dias-multa.', '["Assertiva que destina a multa do art. 29 ao Tesouro Estadual erra: é creditada ao Funad."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-29'
