insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Financiar ou custear a prática de qualquer dos crimes previstos nos arts. 33, caput e §1º, e 34. Pena: reclusão de 8 a 20 anos e 1.500 a 4.000 dias-multa.', '["Financiar ou custear o tráfico ou os petrechos.","Reclusão de 8 a 20 anos e 1.500 a 4.000 dias-multa."]'::jsonb, '["Pena MAIS ALTA da Lei de Drogas.","Pune o financiador, ainda que não pratique o tráfico."]'::jsonb, 'Quem custeia a compra de uma carga de droga responde pelo art. 36.', '["Assertiva que fixa a pena do financiamento em 5 a 15 anos erra: é de 8 a 20 anos."]'::jsonb, '[]'::jsonb, '["Art. 33","Art. 40, VII"]'::jsonb, 'under_review', 'claude'
