insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os crimes previstos nos arts. 33, caput e §1º, e 34 a 37 são inafiançáveis e insuscetíveis de sursis, graça, indulto, anistia e liberdade provisória, vedada a conversão de suas penas em restritivas de direitos. Nos crimes previstos no caput, dar-se-á o livramento condicional após o cumprimento de dois terços da pena, vedada sua concessão ao reincidente específico.', '["Inafiançáveis e insuscetíveis de sursis, graça, indulto, anistia e liberdade provisória.","Vedada a conversão em penas restritivas de direitos.","Livramento condicional após 2/3 da pena, vedado ao reincidente específico."]'::jsonb, '["O STF declarou inconstitucionais a vedação de liberdade provisória e a de conversão em restritivas de direitos (a conversão é possível no tráfico privilegiado).","Livramento: 2/3, e não a fração do Código Penal."]'::jsonb, 'Condenado por tráfico só pode pedir livramento condicional após cumprir dois terços da pena, se não for reincidente específico.', '["Assertiva que fixa o livramento condicional do tráfico em metade da pena erra: são dois terços."]'::jsonb, '[{"termo":"Reincidente específico","significado":"Quem reincide em crime da mesma natureza."}]'::jsonb, '["Art. 33","Lei dos Crimes Hediondos"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-44'
